        // --- jednorazowe podpowiedzi kontekstowe i ich ustawienia
        "hint_title" to t("Wskazówka", "Hint", "Hinweis", "Consejo", "Astuce", "Suggerimento", "Dica", "Підказка", "Tip", "İpucu"),
        "hint_ok" to t("OK", "OK", "OK", "Vale", "OK", "OK", "OK", "Гаразд", "OK", "Tamam"),
        "hint_upgrade" to t("Stać cię na ulepszenie jednostki. Dotknij strzałki.", "You can upgrade a unit. Tap its arrow.", "Du kannst eine Einheit verbessern. Tippe auf den Pfeil.", "Puedes mejorar una unidad. Toca su flecha.", "Vous pouvez améliorer une unité. Touchez sa flèche.", "Puoi potenziare un'unità. Tocca la freccia.", "Podes melhorar uma unidade. Toca na seta.", "Можна поліпшити загін. Натисни стрілку.", "Je kunt een eenheid upgraden. Tik op de pijl.", "Bir birliği geliştirebilirsin. Oka dokun."),
        "hint_cap" to t("Armia pełna. Zbrojownia (kowadło) daje armii +8% obrażeń i HP za każdy zakup.", "Army full. The Armory (anvil) gives your army +8% damage and HP per purchase.", "Armee voll. Die Rüstkammer (Amboss) gibt deiner Armee +8% Schaden und LP pro Kauf.", "Ejército lleno. La armería (yunque) da +8% de daño y PV por compra.", "Armée complète. L'armurerie (enclume) donne +8% de dégâts et PV par achat.", "Esercito pieno. L'armeria (incudine) dà +8% di danni e PS a ogni acquisto.", "Exército cheio. O arsenal (bigorna) dá +8% de dano e vida por compra.", "Армія повна. Зброярня (ковадло) дає армії +8% шкоди та здоров'я за кожну покупку.", "Leger vol. De wapenkamer (aambeeld) geeft +8% schade en HP per aankoop.", "Ordu dolu. Cephanelik (örs) her alımda ordunu %8 güçlendirir: hasar ve can."),
        "hint_rally" to t("Wróg naciera. Użyj Zrywu, by przyspieszyć armię.", "Enemy attack! Use Rally to speed up your army.", "Feindlicher Angriff! Nutze den Ansturm für mehr Tempo.", "¡Ataca el enemigo! Usa el impulso para acelerar tropas.", "L'ennemi attaque ! Utilisez l'élan pour accélérer vos troupes.", "Il nemico attacca! Usa lo slancio per accelerare l'esercito.", "O inimigo ataca! Usa o ímpeto para acelerar o exército.", "Ворог наступає! Використай ривок для прискорення війська.", "Vijand valt aan! Gebruik de stormloop voor extra snelheid.", "Düşman saldırıyor! Ordunu hızlandırmak için Atılımı kullan."),
        "hint_hold" to t("Wróg ma przewagę. Postawa Trzymaj chroni linię obrony.", "Outnumbered? Hold stance keeps your defensive line.", "In Unterzahl? Halten sichert deine Verteidigungslinie.", "¿En inferioridad? Mantener protege tu línea defensiva.", "En infériorité ? Tenir protège votre ligne de défense.", "In minoranza? Tieni protegge la linea difensiva.", "Em desvantagem? Manter protege a linha defensiva.", "Ворог переважає? Оборона захищає твій рубіж.", "In de minderheid? Houden beschermt je verdedigingslijn.", "Azınlıkta mısın? Tut duruşu savunma hattını korur."),
        "hint_veteran" to t("W ostatniej epoce nadwyżka XP daje rangi weteranów.", "In the final era, extra XP earns veteran ranks.", "In der letzten Epoche gibt übrige EP Veteranenränge.", "En la era final, la XP extra da rangos de veterano.", "À l'ère finale, l'XP bonus donne des rangs de vétéran.", "Nell'era finale, gli XP extra danno gradi veterani.", "Na era final, XP extra dá patentes de veterano.", "У фінальній епосі надлишок XP дає ранги ветеранів.", "In het laatste tijdperk geeft extra XP veteranenrangen.", "Son çağda fazla XP, kıdemli rütbeleri kazandırır."),
        "hint_siege" to t("Po 8 minutach presja oblężnicza rośnie co minutę.", "After 8 minutes, siege pressure rises each minute.", "Nach 8 Minuten steigt der Belagerungsdruck jede Minute.", "Tras 8 minutos, la presión de asedio aumenta por minuto.", "Après 8 minutes, la pression de siège augmente chaque minute.", "Dopo 8 minuti, la pressione d'assedio cresce ogni minuto.", "Após 8 minutos, a pressão do cerco cresce a cada minuto.", "Після 8 хвилин тиск облоги щохвилини зростає.", "Na 8 minuten neemt de belegeringsdruk elke minuut toe.", "8 dakikadan sonra kuşatma baskısı her dakika artar."),
        "hint_modifiers" to t("Zasady bitwy", "Battle rules", "Kampfregeln", "Reglas de batalla", "Règles de bataille", "Regole battaglia", "Regras da batalha", "Правила битви", "Gevechtsregels", "Savaş kuralları"),
        "hint_fog" to t("Mgła wojny ukrywa część sił wroga. Osłaniaj bazę.", "Fog of war hides enemy forces. Guard your base.", "Kriegsnebel verbirgt Feinde. Schütze deine Basis.", "La niebla oculta enemigos. Protege tu base.", "Le brouillard cache des ennemis. Protégez votre base.", "La nebbia nasconde nemici. Difendi la base.", "O nevoeiro esconde inimigos. Defende a base.", "Туман війни приховує ворогів. Бережи базу.", "Oorlogsmist verbergt vijanden. Bewaak je basis.", "Savaş sisi düşmanları gizler. Üssünü koru."),
        "hint_card" to t("Wkrótce wybór karty. Wyższa rzadkość to mocniejszy efekt.", "Card choice soon. Higher rarity means stronger effects.", "Bald Kartenwahl: Höhere Seltenheit bringt stärkere Effekte.", "Pronto elegirás carta. Mayor rareza, mayor efecto.", "Choix de carte imminent. Plus rare signifie plus puissant.", "Presto una carta: più rara significa più potente.", "Vem aí uma carta. Maior raridade, efeito mais forte.", "Невдовзі вибір карти. Вища рідкість — сильніший ефект.", "Straks kies je een kaart. Zeldzamer betekent sterker.", "Kart seçimi yakında. Nadir kartların etkisi daha güçlü."),
        "hint_theme" to t("Nadchodzi fala tematyczna. Sprawdź zapowiedź na HUD.", "A themed wave is coming. Check the HUD preview.", "Eine Themenwelle naht. Achte auf die HUD-Vorschau.", "Se acerca una oleada especial. Mira el aviso en pantalla.", "Vague spéciale imminente. Regardez l'annonce à l'écran.", "Arriva un'ondata speciale. Guarda l'avviso sullo schermo.", "Vem uma onda especial. Vê o aviso no ecrã.", "Наближається особлива хвиля. Дивись анонс на екрані.", "Speciale golf op komst. Bekijk de HUD-melding.", "Özel dalga geliyor. Ekrandaki uyarıya bak."),
        "hint_boss_push" to t("Boss odrzuca oddziały. Zbuduj mocny front.", "This boss knocks troops back. Build a strong frontline.", "Dieser Boss stößt Truppen zurück. Halte die Front.", "Este jefe repele tropas. Refuerza la primera línea.", "Ce boss repousse les troupes. Renforcez votre front.", "Questo boss respinge le truppe. Rafforza la prima linea.", "Este chefe repele tropas. Reforça a linha da frente.", "Бос відкидає війська. Зміцни передову.", "Deze baas duwt troepen terug. Versterk de voorlinie.", "Bu patron askerleri geri iter. Ön hattı güçlendir."),
        "hint_boss_aura" to t("Boss przyspiesza pobliskie oddziały. Pokonaj go szybko.", "This boss speeds nearby troops. Defeat it quickly.", "Dieser Boss beschleunigt nahe Truppen. Besiege ihn rasch.", "Este jefe acelera tropas cercanas. Derrótalo rápido.", "Ce boss accélère les troupes proches. Vainquez-le vite.", "Questo boss accelera gli alleati. Sconfiggilo subito.", "Este chefe acelera tropas próximas. Derrota-o depressa.", "Бос прискорює сусідні війська. Усунь його швидко.", "Deze baas versnelt nabije troepen. Versla hem snel.", "Bu patron yakındaki askerleri hızlandırır. Hızla yen."),
        "hint_old_turret" to t("Stara wieża? Ulepsz ją do nowej epoki albo sprzedaj.", "Old-era tower? Upgrade it or sell it.", "Turm aus alter Epoche? Verbessern oder verkaufen.", "¿Torre de era anterior? Mejórala o véndela.", "Tour ancienne ? Améliorez-la ou vendez-la.", "Torre vecchia? Potenziala o vendila.", "Torre antiga? Melhora-a ou vende-a.", "Стара вежа? Поліпши її або продай.", "Oude toren? Upgrade of verkoop hem.", "Eski çağ kulesi mi? Geliştir ya da sat."),
        "hint_daily_battle" to t("Ta próba liczy się do rankingu. Kolejne to trening.", "This attempt counts for ranking. Later tries are practice.", "Dieser Versuch zählt fürs Ranking. Später nur Training.", "Este intento puntúa. Los siguientes son práctica.", "Cet essai est classé. Les suivants sont des entraînements.", "Questo tentativo vale in classifica. Gli altri sono prove.", "Esta tentativa conta. As seguintes são treino.", "Ця спроба рейтингова. Наступні — тренування.", "Deze poging telt voor ranking. Latere zijn oefening.", "Bu deneme sıralamalı. Sonrakiler antrenmandır."),
        "hint_research" to t("Medale zdobywasz nawet za porażki. Kup za nie stałe badania.", "You earn medals even in defeat. Buy permanent research.", "Auch Niederlagen bringen Medaillen für dauerhafte Forschung.", "Ganas medallas incluso al perder. Compra mejoras permanentes.", "Même une défaite donne des médailles pour les recherches.", "Anche perdendo ottieni medaglie per ricerche permanenti.", "Até a derrota dá medalhas para pesquisas permanentes.", "Навіть поразки дають медалі на постійні дослідження.", "Ook verlies levert medailles op voor blijvend onderzoek.", "Yenilgi de madalya kazandırır. Kalıcı araştırma al."),
        "hint_missions" to t("Misje dzienne i tygodniowe dają medale. Odbieraj nagrody.", "Daily and weekly missions earn medals. Claim rewards.", "Tägliche und wöchentliche Missionen geben Medaillen.", "Las misiones diarias y semanales dan medallas. Reclámalas.", "Les missions quotidiennes et hebdomadaires donnent des médailles.", "Missioni giornaliere e settimanali danno medaglie. Ritirale.", "Missões diárias e semanais dão medalhas. Recolhe-as.", "Щоденні та тижневі місії дають медалі. Забирай нагороди.", "Dag- en weekmissies leveren medailles op. Claim beloningen.", "Günlük ve haftalık görevler madalya verir. Ödülleri al."),
        "hint_daily_menu" to t("Tylko pierwsza próba dnia jest rankingowa. Reszta to trening.", "Only the first daily attempt is ranked. Others are practice.", "Nur der erste Tagesversuch zählt fürs Ranking.", "Solo el primer intento diario puntúa. Otros son práctica.", "Seul le premier essai du jour compte au classement.", "Solo il primo tentativo del giorno vale in classifica.", "Só a primeira tentativa diária conta no ranking.", "Лише перша спроба дня рейтингова. Решта — тренування.", "Alleen de eerste dagpoging telt. De rest is oefening.", "Günün yalnız ilk denemesi sıralamalıdır."),
        "hint_endless_menu" to t("Co 5 fal wybierasz kartę, co 10 walczysz z bossem.", "Choose a card every 5 waves and face a boss every 10.", "Alle 5 Wellen eine Karte, alle 10 ein Boss.", "Elige carta cada 5 oleadas y combate un jefe cada 10.", "Choisissez une carte toutes les 5 vagues, un boss toutes les 10.", "Una carta ogni 5 ondate, un boss ogni 10.", "Escolhe uma carta a cada 5 ondas e um chefe a cada 10.", "Кожні 5 хвиль — карта, кожні 10 — бос.", "Elke 5 golven een kaart, elke 10 een eindbaas.", "Her 5 dalgada kart, her 10 dalgada patron."),
        "hint_settings" to t("Podpowiedzi i samouczek", "Hints and tutorial", "Hinweise und Tutorial", "Consejos y tutorial", "Astuces et tutoriel", "Suggerimenti e tutorial", "Dicas e tutorial", "Підказки й навчання", "Tips en tutorial", "İpuçları ve eğitim"),
        "hint_enabled" to t("Podpowiedzi", "Hints", "Hinweise", "Consejos", "Astuces", "Suggerimenti", "Dicas", "Підказки", "Tips", "İpuçları"),
        "hint_replay_label" to t("Samouczek etapu 1", "Stage 1 tutorial", "Tutorial von Stufe 1", "Tutorial de etapa 1", "Tutoriel étape 1", "Tutorial fase 1", "Tutorial etapa 1", "Навчання етапу 1", "Tutorial fase 1", "1. bölüm eğitimi"),
        "hint_reset_label" to t("Pokaż ponownie", "Show again", "Erneut anzeigen", "Mostrar de nuevo", "Afficher à nouveau", "Mostra di nuovo", "Mostrar de novo", "Показати знову", "Opnieuw tonen", "Tekrar göster"),
        "hint_replay" to t("Powtórz samouczek", "Replay tutorial", "Tutorial erneut", "Repetir tutorial", "Revoir le tutoriel", "Ripeti tutorial", "Repetir tutorial", "Повторити навчання", "Tutorial herhalen", "Eğitimi yinele"),
        "hint_reset" to t("Reset podpowiedzi", "Reset hints", "Tipps zurücksetzen", "Reiniciar consejos", "RAZ des astuces", "Azzera i consigli", "Repor dicas", "Скинути підказки", "Tips resetten", "İpuçlarını sıfırla"),
        "hint_confirm" to t("Potwierdź", "Confirm", "Bestätigen", "Confirmar", "Confirmer", "Conferma", "Confirmar", "Підтвердити", "Bevestigen", "Onayla"),
        "hint_tutorial_ready" to t("Samouczek wróci w etapie 1.", "Tutorial will replay in stage 1.", "Tutorial startet in Stufe 1 erneut.", "El tutorial volverá en la etapa 1.", "Le tutoriel reviendra à l'étape 1.", "Il tutorial tornerà nella fase 1.", "O tutorial volta na etapa 1.", "Навчання повториться на етапі 1.", "Tutorial keert terug in fase 1.", "Eğitim 1. bölümde tekrar açılır."),
        "hint_reset_done" to t("Podpowiedzi zresetowane.", "Hints reset.", "Hinweise zurückgesetzt.", "Consejos reiniciados.", "Astuces réinitialisées.", "Suggerimenti azzerati.", "Dicas repostas.", "Підказки скинуто.", "Tips gereset.", "İpuçları sıfırlandı."),
        "tip_cap" to t("Armia pełna, złoto niewydane. Inwestuj w Zbrojownię.", "Army full, gold unused. Invest in the Armory.", "Armee voll, Gold ungenutzt. Rüstkammer ausbauen.", "Ejército lleno y oro sin gastar. Mejora la armería.", "Armée pleine, or inutilisé. Améliorez l'armurerie.", "Esercito pieno, oro inutilizzato. Migliora l'armeria.", "Exército cheio, ouro parado. Melhora o arsenal.", "Армія повна, золото не витрачено. Розвивай арсенал.", "Leger vol, goud over. Investeer in de wapenkamer.", "Ordu dolu, altın harcanmadı. Cephaneliği geliştir."),
        "tip_upgrade" to t("Brak ulepszeń jednostek. Wzmacniaj je przed walką.", "No unit upgrades. Improve troops before fighting.", "Keine Einheitenverbesserung. Rüste Truppen früher auf.", "Sin mejoras de unidades. Refuérzalas antes de luchar.", "Aucune amélioration d'unité. Renforcez vos troupes.", "Nessun potenziamento. Rafforza le truppe prima dello scontro.", "Sem melhorias de unidade. Reforça as tropas antes de lutar.", "Немає поліпшень загонів. Посилюй їх перед боєм.", "Geen eenheidsupgrades. Versterk je troepen eerder.", "Birim geliştirmesi yok. Savaştan önce güçlendir."),
        "tip_counter" to t("Wróg używał kontr na twoją główną rolę. Zmieniaj skład armii.", "Enemy units countered your main role. Vary your army.", "Feinde konterten deine Hauptrolle. Ändere die Truppen.", "El enemigo contrarrestó tu rol principal. Varía tu ejército.", "L'ennemi contrait votre rôle principal. Variez vos unités.", "Il nemico contrastava il tuo ruolo principale. Varia le truppe.", "O inimigo contrariou a tua função principal. Varia tropas.", "Ворог контрив твою основну роль. Змінюй склад війська.", "De vijand counterde je hoofdrol. Wissel eenheden af.", "Düşman ana rolünü karşılıyordu. Birliklerini çeşitlendir."),
